// The shipped payload is fixed application code, not user input. It is decoded
// only when this independent tool is opened; all of its original callbacks and
// storage keys are retained. No network request is needed.
const wbLazyMangaButton=document.getElementById('menuSimpleManga');
function wbLoadManga(event){
 event.stopImmediatePropagation();
 try{
  const payload=document.getElementById('wbMangaPayload'),source=LZString.decompressFromBase64(payload.textContent);if(!source)throw Error('簡易漫画を読み込めませんでした');
  const script=document.createElement('script');script.textContent=source;document.body.append(script);script.remove();
  wbLazyMangaButton.removeEventListener('click',wbLoadManga,true);payload.remove();queueMicrotask(()=>wbLazyMangaButton.click());
 }catch(error){console.error(error);alert('簡易漫画の読み込みに失敗しました。ページを開き直してください。')}
}
wbLazyMangaButton.addEventListener('click',wbLoadManga,true);

